Get-equipments-from-DHIS2.body:
//Get existing tracked entities from DHIS2
fn(state => {
  const pageSize = 100;
  let allTrackedEntityInstances = [];

  const fetchPage = (page) => {
    return get('tracker/trackedEntities', {
      fields: 'trackedEntity,trackedEntityType,orgUnit,enrollments[enrollment,enrollmentDate,orgUnit,program,events[event,occurredAt,orgUnit,program,programStage,dataValues[dataElement,value]],attributes[attribute,value]]',
      ouMode: 'ALL',
      program: 'EThvOOPdWdU',
      programStage: 'QfEdltht9gW',
      paging: true,
      pageSize: pageSize,
      page: page
    })(state).then(response => {
      const { trackedEntities, pager } = response.data;

      if (trackedEntities && trackedEntities.length > 0) {
        allTrackedEntityInstances = [...allTrackedEntityInstances, ...trackedEntities];
      }

      if (pager && pager.page < pager.pageCount) {
        return fetchPage(page + 1);
      } else {
        console.log(`Total tracked entity instances fetched: ${allTrackedEntityInstances.length}`);
        return { 
          ...state, 
          data: { 
            ...state.data, 
            trackedEntityInstances: allTrackedEntityInstances 
          } 
        };
      }
    }).catch(error => {
    console.error('Failed to fetch page:', page, error.response?.data || error.message);
    throw error;
  });
  };

  return fetchPage(1);
});

