Look-Up-Existing-Device-Data-in-DHIS2.body:
fn(state => {
  state.deviceResults = [];
  return state;
});

each(
  $.devices,
  tracker.export('trackedEntities', state => ({
    program: 'pPHkq2q2OrH',
    filter: `SIBMvyNBxab:EQ:${state.data.id}`,
  }))
    .then(state => {
      const device = state.devices[state.index];
      const entities = state.data?.trackedEntities || [];

      if (entities.length === 0) {
        console.error(`No TEI found for PQS code: ${device.id} — skipping`);
        return state;
      }
      if (entities.length > 1) {
        console.error(`Multiple TEIs found for PQS code: ${device.id} — skipping`);
        return state;
      }

      state.deviceResults.push({
        device,
        teiId: entities[0].trackedEntity,
        orgUnit: entities[0].orgUnit,
        trackedEntityType: entities[0].trackedEntityType
      });

      console.log(`TEI found for ${device.id}: ${entities[0].trackedEntity}`);
      return state;
    })
);

