Update-Device-Data.body:
each(
  $.transformedDevices,
  tracker.import(
    'CREATE_AND_UPDATE',
    state => ({
      trackedEntities: [{
        orgUnit: state.data.orgUnit,
        trackedEntityType: state.data.trackedEntityType,
        trackedEntity: state.data.teiId,
        attributes: state.data.attributes,
      }]
    }),
    { atomicMode: 'ALL' }
  )
    .catch((error, state) => {
      const transformed = state.transformedDevices[state.index];
      console.error(`Failed to update TEI ${transformed.teiId}: ${error.message}`);
      state.errorLogs ??= [];
      state.errorLogs.push([new Date(), transformed.teiId, error.message]);
      return state;
    })
    .then(state => {
      const device = state.transformedDevices[state.index];
      console.log(`Successfully updated TEI: ${device.teiId}`);
      return state;
    })
);

Logging.body:
fn(state => {
  console.log(`Devices selected: ${state.devices?.length ?? 0}`);
  console.log(`TEIs resolved: ${state.deviceResults?.length ?? 0}`);
  console.log(`Devices transformed: ${state.transformedDevices?.length ?? 0}`);

  if (state.deviceResults?.length === 0) {
    console.error('No TEIs were resolved — check PQS codes exist in DHIS2');
  }

  if (state.errorLogs?.length > 0) {
    console.error(`${state.errorLogs.length} update(s) failed:`);
    state.errorLogs.forEach(([timestamp, teiId, message]) => {
      console.error(`  ${timestamp} | ${teiId} | ${message}`);
    });
  } else {
    console.log('All TEI updates completed successfully');
  }

  return state;
});
